//! A road's temporary lane layer, over its permanent one.
//!
//! `tests/data/lane_layers.xodr` is generated by `lane_layers.py`. See it
//! for the layout. Road 1's lanes run along +X from the origin, and its
//! right lanes lie at negative `y`.

use xodr::{
    load_file_with_provenance, Advance, LaneId, LanePosition, Layer, LayerPolicy, Point,
    Provenance, RoadNetwork,
};

fn fixture() -> (RoadNetwork, Provenance) {
    load_file_with_provenance("tests/data/lane_layers.xodr").unwrap()
}

/// `P0:-1` for lane -1 of the permanent section with index 0 and
/// `T3:-2` for lane -2 of a temporary section, whose index counts on from
/// the permanent ones.
fn name(prov: &Provenance, id: LaneId) -> String {
    let p = prov.lanes.iter().find(|p| p.lane == id).unwrap();
    let layer = if p.layer == Layer::Temporary {
        "T"
    } else {
        "P"
    };
    format!("{layer}{}:{}", p.section, p.od_id)
}

fn lane(prov: &Provenance, road: &str, section: usize, od_id: i32) -> LaneId {
    prov.lanes
        .iter()
        .find(|p| p.road_id == road && p.section == section && p.od_id == od_id)
        .unwrap_or_else(|| panic!("no lane {od_id} in section {section} of road {road}"))
        .lane
}

fn successors(net: &RoadNetwork, prov: &Provenance, id: LaneId) -> Vec<String> {
    let mut names: Vec<_> = net
        .lane(id)
        .unwrap()
        .successors
        .iter()
        .map(|s| name(prov, *s))
        .collect();
    names.sort();
    names
}

fn predecessors(net: &RoadNetwork, prov: &Provenance, id: LaneId) -> Vec<String> {
    let mut names: Vec<_> = net
        .lane(id)
        .unwrap()
        .predecessors
        .iter()
        .map(|s| name(prov, *s))
        .collect();
    names.sort();
    names
}

#[test]
fn each_lane_knows_its_layer_and_the_sections_count_on_from_the_permanent_ones() {
    let (net, prov) = fixture();
    let on = |road: &str, layer| {
        prov.lanes
            .iter()
            .filter(|p| p.road_id == road && p.layer == layer)
            .count()
    };
    assert_eq!(
        on("1", Layer::Permanent),
        9,
        "three sections of three lanes"
    );
    assert_eq!(on("1", Layer::Temporary), 4, "two sections of two lanes");
    for p in &prov.lanes {
        assert_eq!(net.lane(p.lane).unwrap().layer, p.layer);
    }
    let sections: Vec<_> = prov
        .lanes
        .iter()
        .filter(|p| p.road_id == "1" && p.od_id == -1)
        .map(|p| (p.layer, p.section))
        .collect();
    assert_eq!(
        sections,
        [
            (Layer::Permanent, 0),
            (Layer::Permanent, 1),
            (Layer::Permanent, 2),
            (Layer::Temporary, 3),
            (Layer::Temporary, 4),
        ]
    );
}

#[test]
fn links_join_the_layers_in_both_directions() {
    let (net, prov) = fixture();
    for road in ["1", "2"] {
        let l = |section, od| lane(&prov, road, section, od);
        let s = |section, od| successors(&net, &prov, l(section, od));
        let p = |section, od| predecessors(&net, &prov, l(section, od));
        assert_eq!(s(0, -1), ["P1:-1", "T3:-1"], "road {road}");
        assert_eq!(s(1, -1), ["P2:-1"], "road {road}");
        assert_eq!(s(3, -1), ["T4:-1"], "road {road}");
        assert_eq!(s(4, -1), ["P2:-1"], "road {road}");
        assert_eq!(p(2, -1), ["P1:-1", "T4:-1"], "road {road}");
        assert_eq!(p(3, -1), ["P0:-1"], "road {road}");
        assert_eq!(p(4, -1), ["T3:-1"], "road {road}");
        // The left lane runs against +s and has no temporary lane to link to.
        assert_eq!(s(1, 1), ["P0:1"], "road {road}");
        assert_eq!(s(2, 1), ["P1:1"], "road {road}");
    }
}

#[test]
fn a_temporary_link_with_no_layer_goes_on_to_the_next_temporary_section() {
    let (net, prov) = fixture();
    // Lane -2 says nothing of a layer from section 3 to 4, and back. The
    // spec reads that as permanent, which would leave the layer's own
    // sections unjoined, so the crate takes the temporary layer.
    let l = |section| lane(&prov, "1", section, -2);
    assert_eq!(successors(&net, &prov, l(3)), ["T4:-2"]);
    assert_eq!(predecessors(&net, &prov, l(4)), ["T3:-2"]);
    // And at the end of the temporary layer there is no next one to take.
    assert_eq!(successors(&net, &prov, l(4)), ["P2:-2"]);
}

#[test]
fn a_file_that_lists_the_temporary_layer_first_reads_the_same_roads() {
    let (net, prov) = fixture();
    for section in 0..5 {
        for od in [-1, -2] {
            let a = net.lane(lane(&prov, "1", section, od)).unwrap();
            let b = net.lane(lane(&prov, "2", section, od)).unwrap();
            assert_eq!((a.layer, a.kind, a.width), (b.layer, b.kind, b.width));
            assert_eq!(a.center.length(), b.center.length());
        }
    }
}

#[test]
fn a_temporary_lane_lies_by_its_own_lane_offset() {
    let (net, prov) = fixture();
    let y_at = |section, od, x: f32| {
        let lane = net.lane(lane(&prov, "1", section, od)).unwrap();
        let (point, _) =
            lane.center
                .points()
                .iter()
                .fold((Point::ORIGIN, f32::INFINITY), |best, p| {
                    let d = (p.x - x).abs();
                    if d < best.1 {
                        (*p, d)
                    } else {
                        best
                    }
                });
        point.y
    };
    // The permanent lanes have no offset: lane -1 is centred at -1.75, and
    // the temporary lane -1, 2.5 m wide and shifted 1.5 m, at -2.75.
    assert!((y_at(1, -1, 70.0) + 1.75).abs() < 0.01);
    assert!((y_at(3, -1, 70.0) + 2.75).abs() < 0.01);
    assert!((y_at(3, -2, 70.0) + 5.25).abs() < 0.01);
}

#[test]
fn a_temporary_section_ends_at_its_length() {
    let (net, prov) = fixture();
    let long = |section| {
        net.lane(lane(&prov, "1", section, -1))
            .unwrap()
            .center
            .length()
    };
    assert!((long(3) - 60.0).abs() < 0.1, "40 to 100 m");
    assert!(
        (long(4) - 60.0).abs() < 0.1,
        "from 100 m, 60 m long, not on to 200 m"
    );
}

#[test]
fn the_surface_mesh_is_the_permanent_layer_and_the_temporary_mesh_the_rest() {
    let (net, _) = fixture();
    let layer_of = |id: LaneId| net.lane(id).unwrap().layer;
    let surface = net.surface_mesh();
    let temporary = net.temporary_mesh();
    assert!(!surface.lanes.is_empty() && !temporary.lanes.is_empty());
    assert!(surface
        .lanes
        .iter()
        .all(|s| layer_of(s.lane) == Layer::Permanent));
    assert!(temporary
        .lanes
        .iter()
        .all(|s| layer_of(s.lane) == Layer::Temporary));
    assert_eq!(
        surface.lanes.len() + temporary.lanes.len(),
        net.lanes().len()
    );
}

#[test]
fn a_temporary_lane_wins_where_it_holds_the_point_unless_the_policy_says_not() {
    let (net, prov) = fixture();
    let layer = |at: Point, policy| {
        let (id, _) = net.nearest_lane_with(at, policy).unwrap();
        (net.lane(id).unwrap().layer, name(&prov, id))
    };
    let over = Point::new(70.0, -2.75, 0.0);
    assert_eq!(layer(over, LayerPolicy::Temporary).0, Layer::Temporary);
    assert_eq!(
        net.nearest_lane(over).unwrap().0,
        net.nearest_lane_with(over, LayerPolicy::Temporary)
            .unwrap()
            .0
    );
    assert_eq!(
        layer(over, LayerPolicy::PermanentOnly),
        (Layer::Permanent, "P1:-1".to_string())
    );
    // Beside the temporary lane, and where there is none, the permanent one.
    for at in [Point::new(70.0, -0.5, 0.0), Point::new(20.0, -2.75, 0.0)] {
        assert_eq!(
            layer(at, LayerPolicy::Temporary).0,
            Layer::Permanent,
            "{at:?}"
        );
    }
}

#[test]
fn lane_position_finds_the_temporary_lane_by_its_borders() {
    let (net, prov) = fixture();
    let at = |y: f32, policy| {
        let position = net
            .lane_position_with(Point::new(70.0, y, 0.0), policy)
            .unwrap();
        name(&prov, position.lane)
    };
    assert_eq!(at(-2.75, LayerPolicy::Temporary), "T3:-1");
    assert_eq!(at(-2.75, LayerPolicy::PermanentOnly), "P1:-1");
    assert_eq!(
        at(-0.5, LayerPolicy::Temporary),
        "P1:-1",
        "inside no temporary lane"
    );
}

#[test]
fn a_route_and_an_advance_may_leave_the_permanent_layer_only_under_the_default_policy() {
    let (net, prov) = fixture();
    let start = LanePosition {
        lane: lane(&prov, "1", 0, -1),
        s: 30.0,
        offset: 0.0,
    };
    let kinds = |policy| {
        let mut layers: Vec<_> = net
            .advance_with(start, 20.0, policy)
            .iter()
            .map(|a| match a {
                Advance::Reached(at) | Advance::DeadEnd { at, .. } => name(&prov, at.lane),
            })
            .collect();
        layers.sort();
        layers
    };
    assert_eq!(kinds(LayerPolicy::Temporary), ["P1:-1", "T3:-1"]);
    assert_eq!(kinds(LayerPolicy::PermanentOnly), ["P1:-1"]);
    let (from, to) = (Point::new(5.0, -1.75, 0.0), Point::new(195.0, -1.75, 0.0));
    let permanent = net
        .route_with(from, to, LayerPolicy::PermanentOnly)
        .unwrap();
    assert!(
        permanent.iter().all(|p| (p.y + 1.75).abs() < 0.01),
        "stays on lane -1"
    );
    assert!(net.route(from, to).is_some());
}

#[test]
fn a_validity_picks_the_lanes_of_its_layer() {
    let (net, prov) = fixture();
    let lanes_of = |signal: &str| {
        let placed = prov.signals.iter().find(|p| p.od_id == signal).unwrap();
        let mut names: Vec<_> = net.signals()[placed.signal.0]
            .lanes
            .iter()
            .map(|l| name(&prov, *l))
            .collect();
        names.sort();
        names
    };
    assert_eq!(
        lanes_of("any"),
        ["P1:-1", "P1:-2", "P1:1", "T3:-1", "T3:-2"]
    );
    assert_eq!(lanes_of("permanent"), ["P1:-1", "P1:-2"]);
    assert_eq!(lanes_of("temporary"), ["T3:-1", "T3:-2"]);
    assert_eq!(lanes_of("both"), ["P1:-1", "T3:-1"]);
}

#[test]
fn a_junction_lane_link_joins_the_layers_it_names() {
    let (net, prov) = fixture();
    let arm_permanent = lane(&prov, "11", 0, -1);
    let arm_temporary = lane(&prov, "11", 1, -1);
    assert_eq!(net.lane(arm_temporary).unwrap().layer, Layer::Temporary);
    assert_eq!(successors(&net, &prov, arm_permanent), ["P0:-1"]);
    // Only the link that names the temporary layer on both ends joins the
    // temporary lanes. The permanent lane never goes to the temporary one.
    assert_eq!(successors(&net, &prov, arm_temporary), ["T1:-1"]);
}

#[test]
fn the_marks_of_a_temporary_lane_lie_on_it() {
    let (net, prov) = fixture();
    let temporary: Vec<_> = net
        .road_marks()
        .iter()
        .filter(|m| {
            [m.left, m.right]
                .into_iter()
                .flatten()
                .any(|l| net.lane(l).unwrap().layer == Layer::Temporary)
        })
        .collect();
    assert!(!temporary.is_empty());
    assert!(temporary
        .iter()
        .all(|m| m.color == "yellow" || m.color == "standard"));
    assert!(prov
        .road_marks
        .iter()
        .any(|m| m.road_id == "1" && m.section >= 3));
}
